INSERT INTO `t_student_wrong_question` VALUES (1,1,5,'{\"stem\":\"函数 f(x)=x² 在 x=2 处的导数是多少？\",\"options\":{\"A\":\"2\",\"B\":\"4\",\"C\":\"6\",\"D\":\"8\"}}','A','B','高等数学,导数','误把 x² 的导数记成了 x。',1,'MANUAL',NULL,'2026-09-02 11:02:36','2026-09-02 11:02:36',0),(2,1,5,'{\"stem\":\"若函数g(x) = e^x - x在点x=0处的导数值是：\",\"options\":{\"A\":\"-1\",\"B\":\"0\",\"C\":\"1\",\"D\":\"e\"}}','B','C','导数,指数函数','AI 相似题练习答错，已自动加入错题本。',1,'AI_GENERATE',NULL,'2026-09-02 11:21:27','2026-09-02 11:21:27',0),(3,1,5,'{\"stem\":\"设h(x) = ln(x^2 + 1)，则h\'(x)为：\",\"options\":{\"A\":\"2x / (x^2 + 1)\",\"B\":\"x / (x^2 + 1)\",\"C\":\"(x^2 - 1) / (x^2 + 1)\",\"D\":\"(x^2 + 1) / x\"}}','C','A','导数,对数函数','AI 相似题练习答错，已自动加入错题本。',1,'AI_GENERATE',NULL,'2026-09-02 11:21:29','2026-09-02 11:21:29',0);
